-- Seed INDESCALE — catégorie « Home cinéma / salle de projection privée » (15 cibles enrichies).
-- À exécuter UNE FOIS dans Supabase → SQL Editor, après schema.sql. Idempotent par (app, categorie, entreprise).
create unique index if not exists prospects_cine_uniq
  on prospects (app, categorie, entreprise)
  where app = 'indescale' and place_id is null;

on conflict do nothing;
